-- IPA 2020-06-14 Q65–80: source-reviewed adaptations and verified repeats.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20200614-q65','exam-fe','グリーン調達','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問65・改編】グリーン調達の説明はどれか。','[{"id":"a","text":"環境保全活動を公表して投資家から資金を募る"},{"id":"b","text":"環境保全に役立つ製品の表示に関する国際規格を指す"},{"id":"c","text":"自然エネルギーによる電力を取引可能にする証書を指す"},{"id":"d","text":"品質や価格に加え環境負荷の小さい製品やサービスを環境負荷低減に努める事業者から優先購入する"}]','"d"','環境に配慮した製品やサービスを優先的に調達すること。中文：绿色采购是在满足质量和价格要求的同时优先采购环境负担较小的产品和服务。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q66','exam-fe','コアコンピタンス','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問66・改編】コアコンピタンスに該当するものはどれか。','[{"id":"a","text":"主な事業領域の高い成長率"},{"id":"b","text":"競合他社より効率の高い生産システム"},{"id":"c","text":"参入予定分野の競合状況"},{"id":"d","text":"収益性の高い事業分野での市場シェア"}]','"b"','コアコンピタンスは企業固有の競争優位を支える中核的な能力。優れた生産システムはその例になり得る。中文：核心竞争力是支撑企业竞争优势的独特能力，例如高效率的生产系统。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q67','exam-fe','規模の経済とシナジー','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問67・改編】ビールと清涼飲料水の生産量とコストは次のとおり（量は万本、コストは万円）。A=(ビール20,飲料0,1500)、B=(40,0,3300)、C=(0,10,500)、D=(0,20,1100)、E=(20,10,1900)、F=(40,20,4200)。規模のメリットとシナジー効果について適切なものはどれか。','[{"id":"a","text":"規模のメリットはあるがシナジー効果はない"},{"id":"b","text":"規模のメリットはないがシナジー効果はある"},{"id":"c","text":"規模のメリットとシナジー効果がともにある"},{"id":"d","text":"規模のメリットとシナジー効果がともにない"}]','"b"','単独生産量を倍にするとコストは2倍超（3300>3000、1100>1000）なので規模のメリットはない。複合生産は1900<1500+500、4200<3300+1100でシナジーがある。中文：单独增产一倍时成本超过两倍；共同生产的成本低于分别生产之和，因此有协同效应而无规模经济。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q68','exam-fe','デルファイ法','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問68・改編】複数の専門家に質問し、回答を集約・フィードバックして再質問を繰り返し、結果を統計的に処理する未来予測手法はどれか。','[{"id":"a","text":"クロスセクション法"},{"id":"b","text":"シナリオライティング法"},{"id":"c","text":"親和図法"},{"id":"d","text":"デルファイ法"}]','"d"','デルファイ法は専門家への複数回の質問とフィードバックを通じて予測や意見を集約する。中文：德尔菲法通过多轮专家调查与反馈汇总预测。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q69','exam-fe','技術のSカーブ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問69・改編】技術が導入、成長、成熟、衰退を経て次の技術フェーズへ移る進化過程を表すものはどれか。','[{"id":"a","text":"技術のSカーブ"},{"id":"b","text":"需要曲線"},{"id":"c","text":"バスタブ曲線"},{"id":"d","text":"ラーニングカーブ"}]','"a"','技術の進歩や普及の段階をS字状の曲線で表す。中文：技术S曲线用于表示技术发展的不同阶段。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q71','exam-fe','アクセシビリティ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問71・改編】アクセシビリティの説明として適切なものはどれか。','[{"id":"a","text":"住民基本台帳をネットワークで管理し行政を合理化すること"},{"id":"b","text":"異なるコンピュータ間のソフトウェアやデータの相互運用性"},{"id":"c","text":"製品の生産から消費や廃棄までの履歴を追跡できること"},{"id":"d","text":"高齢者や障害者を含む幅広い利用者にとってのソフトウェアやWebサイトなどの利用しやすさ"}]','"d"','アクセシビリティは多様な人が情報やサービスにアクセスし利用できること。中文：无障碍性关注不同能力和年龄的用户是否能够使用信息与服务。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q72','exam-fe','生産能力の制約','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問72・改編】製品を月1000個作る。工程A〜Dの（1個当たり製造時間、機械台数、1台当たり月間稼働能力）はA=(0.4時間,3台,150時間)、B=(0.3,2,160)、C=(0.7,4,170)、D=(1.2,7,180)。能力不足となる工程はどれか。','[{"id":"a","text":"A"},{"id":"b","text":"B"},{"id":"c","text":"C"},{"id":"d","text":"D"}]','"c"','必要時間はA400、B300、C700、D1200時間。能力は各450、320、680、1260時間なのでCが20時間不足する。中文：各工序需要400、300、700、1200小时，能力分别为450、320、680、1260小时，C不足20小时。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q73','exam-fe','クラウドソーシング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問73・改編】クラウドソーシングの説明はどれか。','[{"id":"a","text":"インターネット取引の決済にディジタル化した貨幣を使う"},{"id":"b","text":"事業資金の目的を公表して資金提供者を募る"},{"id":"c","text":"商品と販売条件を公表して入札者が価格を競う"},{"id":"d","text":"発注者が業務内容と条件をインターネット上で公表し受注者を募る"}]','"d"','ネット上で不特定多数に業務を発注する仕組み。資金を募るクラウドファンディングとは異なる。中文：众包通过网络公开任务和条件，向广泛的承接者发包；募集资金是众筹。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q74','exam-fe','ロングテール','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問74・改編】ロングテールの説明はどれか。','[{"id":"a","text":"売上の80%が上位20%の売れ筋によって構成される経験則"},{"id":"b","text":"オンラインショップなどで販売機会が少ない商品も幅広く取りそろえ、機会損失のリスクを減らす"},{"id":"c","text":"複数事業で経営資源を共有し独立運営よりコストを下げる"},{"id":"d","text":"ネットワークの価値が加入者数の2乗に近似して比例する"}]','"b"','ネット販売では個々の需要が少ない商品も多数集めることで売上機会を得られる。中文：长尾效应通过大量销售频率低的商品汇集需求，减少错失销售机会。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q75','exam-fe','CIO','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問75・改編】CIOの説明はどれか。','[{"id":"a","text":"経営戦略の立案と業務執行を統括する最高責任者"},{"id":"b","text":"資金調達や財務報告など財務戦略と執行を統括する最高責任者"},{"id":"c","text":"技術戦略や研究開発計画の立案と執行を統括する最高責任者"},{"id":"d","text":"情報管理や情報システムの戦略立案と執行を統括する最高責任者"}]','"d"','CIOは最高情報責任者。財務はCFO、技術はCTOなどの役割。中文：CIO是首席信息官，负责信息及信息系统战略。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q76','exam-fe','パレート図','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問76・改編】パレート図の説明はどれか。','[{"id":"a","text":"原因と結果を魚の骨の形に整理する"},{"id":"b","text":"時系列のばらつきを折れ線と管理限界線で管理する"},{"id":"c","text":"区間ごとのデータ数を棒グラフにし、ばらつきを捉える"},{"id":"d","text":"項目を出現頻度の高い順に棒で並べ、累積和を折れ線で示して問題を絞り込む"}]','"d"','パレート図は頻度の降順の棒と累積曲線を組み合わせ、重点課題を把握する。中文：帕累托图将各项按频次降序排列，并以折线显示累计值，帮助识别重点问题。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q77','exam-fe','2機械の加工順序','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問77・改編】製品A、B、Cはそれぞれ機械M1→M2の順に加工し、1台の機械は同時に1製品だけ加工できる。所要時間はA=(M1:7,M2:3)、B=(5,6)、C=(4,2)。ある製品のM1加工後、別の製品を続けてM1で加工できる。全製品の完了までの時間が最短となる順序はどれか。','[{"id":"a","text":"A→C→B"},{"id":"b","text":"B→A→C"},{"id":"c","text":"B→C→A"},{"id":"d","text":"C→B→A"}]','"b"','各選択肢の完了時刻は順に22、18、19、19。B→A→CではM2でBが5〜11、Aが12〜15、Cが16〜18に加工され最短18。中文：分别计算两台机器的先后关系，四个顺序总耗时为22、18、19、19，B→A→C最短。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q78','exam-fe','損益分岐と客数','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問78・改編】喫茶店の客1人当たり売上500円、変動費100円、固定費30万円／月。月20日営業、10席。月10万円の利益を得るため、1席当たり1日何人の客が必要か。','[{"id":"a","text":"3.75"},{"id":"b","text":"4"},{"id":"c","text":"4.2"},{"id":"d","text":"5"}]','"d"','1人当たり限界利益は400円。必要客数は(300000+100000)÷400＝月1000人。1000÷20日÷10席＝1席1日5人。中文：每位顾客贡献400日元，月需1000人，除以20天和10个座位，每席每天5人。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q80','exam-fe','集団思考','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問80・改編】技術者倫理の遵守を妨げる集団思考の説明はどれか。','[{"id":"a","text":"異なる視点から見られず客観性に欠けること"},{"id":"b","text":"組織内の権威に無批判に服従すること"},{"id":"c","text":"正しいことを知りながら実行する勇気や決断力に欠けること"},{"id":"d","text":"連帯性の強いチームが批判的思考を欠き不合理な合意に達すること"}]','"d"','集団思考は結束や合意を優先するあまり反対意見や批判的検討が抑えられる現象。中文：群体思维因过度追求一致而压制质疑，可能导致不合理决策。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption');
